package app.ui.media

import java.util.Base64
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertNotEquals
import kotlin.test.assertTrue

class AnimatedGifTest {
    @Test
    fun `decoder preserves animated GIF frames and timing`() {
        decodeGif(Base64.getDecoder().decode(TWO_FRAME_GIF)).use { animation ->
            assertEquals(2, animation.frames.size)
            assertEquals(1_000L, animation.frames.sumOf { it.durationMillis })
            assertTrue(animation.repetitionCount < 0)

            val firstPixels = animation.frames[0].pixelColors()
            val secondPixels = animation.frames[1].pixelColors()
            assertNotEquals(firstPixels, secondPixels)
        }
    }

    @Test
    fun `decoder rejects content that is not GIF`() {
        assertFailsWith<IllegalArgumentException> {
            decodeGif("not a gif".encodeToByteArray())
        }
    }

    private fun GifAnimation.Frame.pixelColors(): List<Int> = buildList {
        repeat(bitmap.height) { y ->
            repeat(bitmap.width) { x ->
                add(bitmap.getColor(x, y))
            }
        }
    }

    private companion object {
        const val TWO_FRAME_GIF =
            ""
    }
}
